#!/usr/bin/env bash
set -euo pipefail
ROUND="${1:?round}" AGG="${2:?aggregation}"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; PROJECT_DIR="$(cd "$SCRIPT_DIR/../.." && pwd)"; REPO_DIR="$(cd "$PROJECT_DIR/.." && pwd)"; cd "$REPO_DIR"
if command -v module >/dev/null 2>&1; then module purge >/dev/null 2>&1 || true; module load StdEnv/2023 python/3.11 rdkit/2025.09.4; module load cuda/12.6 2>/dev/null || true; fi
PYTHON_BIN="${SUCC_PYTHON_BIN:-${PYTHON_BIN:-python3}}"; SEED="${P816_SEED:-7}"; P814="$PROJECT_DIR/outputs/p8_1_4_full_smiles_multitask_r1/seed_${SEED}"; OUT="$PROJECT_DIR/outputs/p8_1_6_macro_group_rl/${ROUND}/seed_${SEED}"; P813="$PROJECT_DIR/outputs/p8_1_3_macro_graph"
BASE="$P814/policy/unified_smiles_generator.pt"; mkdir -p "$OUT/policy"; export PYTHONPATH="$PROJECT_DIR:$PROJECT_DIR/experiments/unified_smiles_generator${PYTHONPATH:+:$PYTHONPATH}" OMP_NUM_THREADS="${SLURM_CPUS_PER_TASK:-8}" MKL_NUM_THREADS="${SLURM_CPUS_PER_TASK:-8}" TOKENIZERS_PARALLELISM=false
for f in "$BASE" "$P814/data/mixed_train.csv" "$P814/data/mixed_features/query_tokens.npy" "$P813/r1/seed_${SEED}/summary.json" "$P813/r2/seed_${SEED}/summary.json"; do [[ -e "$f" ]] || { echo "missing $f" >&2; exit 2; }; done
"$PYTHON_BIN" "$SCRIPT_DIR/preflight.py" --macro-r1 "$P813/r1/seed_${SEED}/summary.json" --macro-r2 "$P813/r2/seed_${SEED}/summary.json" --mixed "$P814/data/mixed_train.csv" --features "$P814/data/mixed_features" --output "$OUT/preflight.json"
echo "P8.1.6 $ROUND: one terminal full-SMILES trajectory reward, aggregation=$AGG"
"$PYTHON_BIN" "$SCRIPT_DIR/full_smiles_entrypoint.py" group-rl --train-csv "$P814/data/mixed_train.csv" --condition-features-dir "$P814/data/mixed_features" --condition-layout unified --resume-checkpoint "$BASE" --trainable-scope all --output-dir "$OUT/policy" --epochs 1 --limit 256 --batch-size 4 --lr 1e-6 --weight-decay 0 --rollouts-per-prompt 8 --rl-objective grpo --grpo-update-epochs 1 --sft-weight 1.0 --reference-kl-weight 0.08 --reward-mode auto --reward-aggregation "$AGG" --reward-valid-weight 0.5 --reward-strict-weight 2.0 --reward-joint-bonus-weight 2.0 --reward-bottleneck-weight 0.5 --reward-softmin-weight 1.0 --reward-softmin-temperature 0.25 --reward-source-similarity-weight 2.0 --reward-source-similarity-threshold 0.65 --reward-source-copy-penalty 1.0 --smiles-grammar-constraint --max-new-tokens 100 --temperature 0.8 --top-k 32 --top-p 0.95 --parallel-samples 4 --max-parallel-sequences 256 --seed "$SEED" --device auto
bash "$SCRIPT_DIR/run_eval.sh" "$ROUND" "$AGG" "$OUT/policy/unified_smiles_generator_group_rl.pt" "$OUT"
